const paths={home:'M3 10 12 3l9 7M5 9v12h5v-7h4v7h5V9',calendar:'M5 5h14a2 2 0 0 1 2 2v13H3V7a2 2 0 0 1 2-2Zm2-3v6m10-6v6M3 11h18m-13 4h1m6 0h1m-8 3h1',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m18 0v-2a4 4 0 0 0-3-3.87M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8Zm7-7.87a4 4 0 0 1 0 7.75',gift:'M3 8h18v4H3Zm2 4v9h14v-9M12 8v13m0-13H8a3 3 0 1 1 3-3l1 3Zm0 0h4a3 3 0 1 0-3-3l-1 3Z',message:'M21 3H3v15h5l4 4 4-4h5Z M7 8h10M7 12h6',scissors:'M6 6l14 14M6 18 20 4M8 6a3 3 0 1 0-6 0 3 3 0 0 0 6 0Zm0 12a3 3 0 1 0-6 0 3 3 0 0 0 6 0Z',arrow:'M5 12h14m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',back:'m15 5-7 7 7 7',check:'m5 12 4 4L19 6',star:'m12 3 2.8 5.7 6.3.9-4.5 4.4 1 6.2L12 17.3l-5.6 2.9 1.1-6.2L3 9.6l6.2-.9Z',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9Zm-8 13h4',chart:'M4 3v18h17M8 17v-5m5 5V8m5 9V4',wallet:'M3 6h17v15H3Zm0 0 14-4v4m-2 6h5v4h-5Z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8Zm-2-5h4l1 3 3 1 3-1 2 3-2 3 1 3-2 3-3-1-3 2-1 3h-4l-1-3-3-1-3 1-2-3 2-3-1-3 2-3 3 1 3-2Z',clock:'M12 7v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Z',crown:'m3 7 4 4 5-7 5 7 4-4-2 13H5Z',send:'m22 2-7 20-4-9L2 9 22 2ZM11 13 22 2',close:'m6 6 12 12M6 18 18 6'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.chevron}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:Number.isInteger(n)?0:2}).format(n);
const barbers=[{id:'alex',name:'Lara',short:'Lara',specialty:'Barber · HAIRFLIX',img:'lara.png',focus:'92% 0%',rating:'5.0',reviews:0,bookings:42,ticket:63},{id:'jordan',name:'Jose',short:'Jose',specialty:'Barber · HAIRFLIX',img:'jose.png',focus:'70% 32%',rating:'4.9',reviews:0,bookings:38,ticket:55}];
barbers.push({id:'watkins',name:'Watkins',short:'Watkins',specialty:'Barber · HAIRFLIX',img:'watkins.png',focus:'center',bookings:0,ticket:40});
function activeBarberId(){return state.staffId||'alex';}
function servicesFor(id){return services;}
function serviceIcon(s){return icon('scissors');}
function activeStaff(){return barbers.find(b=>b.id===activeBarberId())||barbers[0];}

const services=[{id:'cut',name:'Signature haircut',price:30,min:30,desc:'Consultation, precision cut & finish'},{id:'combo',name:'Haircut + beard',price:40,min:45,desc:'A complete refresh, tailored to you'},{id:'beard',name:'Beard sculpt',price:20,min:20,desc:'Shape, line-up & hot towel finish'},{id:'kids',name:'Kids haircut',price:25,min:30,desc:'For the next generation · 12 & under'}];
try{const catalog=JSON.parse(localStorage.getItem('hairflix-demo-v1')||'{}').extras?.catalog;if(Array.isArray(catalog)&&catalog.length&&catalog.every(x=>x.id&&x.name&&Number.isFinite(x.price)&&x.price>=0&&x.price<=1000&&Number.isInteger(x.min)))services.splice(0,services.length,...catalog);}catch{}
for(const item of [{id:'eyebrows',name:'Eyebrows',price:12,min:10,desc:'Eyebrow shaping and tidy-up'},{id:'hydrafacial',name:'Hydrafacial',price:120,min:60,desc:'Facial treatment'}])if(!services.some(s=>s.id===item.id))services.push(item);
const times=Array.from({length:40},(_,i)=>{const n=9*60+i*15;return `${Math.floor(n/60)%12||12}:${String(n%60).padStart(2,'0')} ${n>=720?'PM':'AM'}`;});
const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Phoenix',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date()),days=Array.from({length:7},(_,i)=>{const d=new Date(today+'T12:00:00');d.setDate(d.getDate()+i+1);return iso(d)});
const dateObj=s=>new Date(s+'T12:00:00');
const pretty=(s,opts={weekday:'short',month:'short',day:'numeric'})=>dateObj(s).toLocaleDateString('en-US',opts);
let bookings=[],checked={},messages=[];
try{const saved=JSON.parse(localStorage.getItem('hairflix-demo-v1')||'{}');if(Array.isArray(saved.bookings))bookings=saved.bookings.map(b=>b.barber==='chris'?{...b,barber:'jordan'}:b).filter(b=>barbers.some(x=>x.id===b.barber)&&(b.bookedServices?.length||services.some(x=>x.id===b.service))&&/^\d{4}-\d{2}-\d{2}$/.test(b.date)&&times.includes(b.time));checked=saved.checked||{};messages=Array.isArray(saved.messages)?saved.messages:[];}catch{}
const state={role:window.HFEntryRole||'Customer',view:'home',step:0,barber:'alex',service:'cut',date:days[0],time:'',tip:0,editing:null,latest:null,period:'Week',calendarDate:today,cancelId:null,tab:'appointments'};
const B=()=>barbers.find(b=>b.id===state.barber);
function selectedServices(){const ids=state.services||[state.service];const prior=state.editing?bookings.find(b=>b.id===state.editing)?.bookedServices:null;return ids.map(id=>prior?.find(s=>s.id===id)||services.find(s=>s.id===id)).filter(Boolean);}
function S(){const list=selectedServices();return {id:list[0]?.id,name:list.map(s=>s.name).join(' + ')||'Choose your services',price:list.reduce((n,s)=>n+s.price,0),min:list.reduce((n,s)=>n+s.min,0)};}
function bookingDuration(b){return b.bookedServices?.reduce((n,s)=>n+s.min,0)||b.durationMin||services.find(s=>s.id===b.service)?.min||30;}
function bookingName(b){return b.bookedServices?.map(s=>s.name).join(' + ')||services.find(s=>s.id===b.service)?.name||'Visit';}

const photo=(b,cls='avatar')=>!b.img?`<span class="account-initials ${cls}" role="img" aria-label="${esc(b.name)}">${esc(b.name.split(/\s+/).slice(0,2).map(s=>s[0]).join(''))}</span>`:['lara.png','jose.png'].includes(b.img)?`<span class="${cls} staff-photo" role="img" aria-label="${esc(b.name)}, barber" style="background-image:url('assets/${esc(b.img)}');background-position:${b.focus||'center'}"></span>`:`<img class="${cls}" src="assets/${esc(b.img)}" alt="${esc(b.name)}" loading="lazy">`;
const logo=()=>`<div><div class="logo">HAIRFL<span class="pole">I</span>X</div><div class="brand-caption">Barbershop · ${shops[extras.location||'scottsdale'].name}</div></div>`;
const button=(label,action,cls='',extra='')=>`<button class="btn ${cls}" data-action="${action}" ${extra}>${label}</button>`;
const footnote=()=>'';
function save(){try{localStorage.setItem('hairflix-demo-v1',JSON.stringify({bookings,checked,messages,extras}));}catch{toast('Browser storage unavailable. Changes will last for this session.');}}
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),3500);}
function go(view){state.view=view;state.cancelId=null;render();document.querySelector('#main').focus({preventScroll:true});window.scrollTo(0,0);}
function startBooking(){state.step=0;state.editing=null;state.time='';const first=servicesFor(state.barber).find(s=>s.active!==false)?.id;state.services=first?[first]:[];state.service=first||'cut';go('book');}
function navItems(){return state.role==='Customer'?[['home','home','Home'],['book','calendar','Book'],['bookings','users','My visits'],['cApproval','wallet','Checkout'],['more','settings','More']]:state.role==='Barber Pro'?[['home','calendar','Today'],['pCalendar','calendar','Calendar'],['pTickets','scissors','Tickets'],['clients','users','Clients'],['more','settings','More']]:[['home','home','Overview'],['calendar','calendar','Calendar'],['team','users','Team'],['reports','chart','Reports'],['more','settings','More']];}
function render(){const nav=navItems();document.querySelector('#app').innerHTML=`<aside class="sidebar">${logo()}<nav class="side-nav" aria-label="Main navigation">${nav.map(([v,i,l])=>`<button class="nav-item ${state.view===v?'active':''}" data-view="${v}" ${state.view===v?'aria-current="page"':''}>${icon(i)}${l}</button>`).join('')}</nav><div class="side-bottom">${state.role==='Barber Pro'?photo(activeStaff()):'<span class="account-initials">'+(state.role==='Customer'?'JB':'HQ')+'</span>'}<div><strong>${state.role==='Customer'?'John B.':state.role==='Barber Pro'?'Lara':'Shop owner'}</strong><br><small>${state.role==='Customer'?'Your next great cut awaits.':state.role==='Barber Pro'?'Your chair. Your craft.':'McCormick Ranch'}</small></div></div></aside><div class="workspace"><header class="topbar"><div class="mobile-brand">${logo()}</div><span class="location">${icon('pin')} ${shops[extras.location||'scottsdale'].name} <span class="dot"></span> Open until 6 PM</span><div class="top-right"><select class="location-switch" id="shop-location-switch" aria-label="Shop location">${Object.entries(shops).map(([id,shop])=>`<option value="${id}" ${extras.location===id?'selected':''}>${shop.name}</option>`).join('')}</select><a class="role-entry-link" href="/login/">Switch workspace</a><button class="icon-btn" data-action="notifications" aria-label="Notifications">${icon('bell')}</button></div></header><div class="prototype-tools"><button data-x="try-ticket">Try sample live ticket</button></div><main class="content" id="main" tabindex="-1">${view()}${footnote()}</main><nav class="bottom-nav" aria-label="Mobile navigation">${nav.map(([v,i,l])=>`<button class="${state.view===v?'active':''}" data-view="${v}" ${state.view===v?'aria-current="page"':''}>${icon(i)}${l}</button>`).join('')}</nav></div>`;}
function head(title,sub,extra=''){return `<div class="page-head"><div><h1>${title}</h1>${sub?`<p>${sub}</p>`:''}</div>${extra}</div>`;}
function view(){const extraPage=renderExtraView(state.view);if(extraPage!==null)return extraPage;if(state.view==='book')return booking();if(state.view==='success')return success();if(state.view==='bookings')return myBookings();if(state.view==='rewards')return rewards();if(state.view==='messages')return chat();if(state.view==='clients')return clients();if(state.view==='earnings')return earnings();if(state.view==='availability')return availability();if(state.view==='team')return team();if(state.view==='reports')return reports();if(state.view==='settings')return settings();if(state.view==='calendar')return proCalendar(true);return state.role==='Customer'?customerHome():state.role==='Barber Pro'?proHome():ownerHome();}
function rewardCard(){return `<div class="reward"><div class="reward-head"><span class="logo">HAIRFLIX</span>${icon('crown')}</div><span class="reward-label">THE GOOD LOOKS CLUB</span><div class="punches">${[0,1,2,3,4].map((_,i)=>`<span class="punch ${i<3?'filled':''}">${i<3?icon('scissors'):''}</span>`).join('')}</div><h3>Two more cuts. $10 on us.</h3><p>Your next reward is closer than you think.</p><button class="text-btn" data-view="rewards">View my punch card ${icon('arrow')}</button></div>`;}
function barberCard(b){return `<button class="barber-card" data-barber="${b.id}" data-start="true">${photo(b,'barber-photo')}<div class="barber-info"><h3>${b.name}</h3><p>${b.specialty}</p><div class="available">Next available · Tomorrow</div></div></button>`;}
function upcoming(){return bookings.filter(b=>b.client==='John B.'&&!['cancelled','completed'].includes(b.status)&&b.date>=today).sort((a,b)=>a.date.localeCompare(b.date)||minutes(a.time)-minutes(b.time))[0];}
function customerHome(){const next=upcoming();return `${head('Looking sharp starts here.','A familiar chair. A fresh perspective.',`<span class="pill">${icon('clock')} ${pretty(today)}</span>`)}<div class="home-grid"><section class="hero"><img src="assets/shop.jpg" alt="Barber carefully finishing a beard trim"><div class="hero-content">${logo()}<h2>Your time.<br>Your barber.<br>Your kind of cut.</h2><p>Good conversation. Exceptional craft.<br>Come in as you are. Leave feeling your best.</p>${button(`${icon('calendar')} Book an appointment ${icon('arrow')}`,'start','full')}</div></section><div class="home-aside">${rewardCard()}<section class="next-visit"><div class="row between"><small>${next?'YOUR NEXT VISIT':'MAKE IT A RITUAL'}</small>${icon('calendar')}</div><h3>${next?`${pretty(next.date)} · ${next.time}`:'A little time for yourself.'}</h3><p>${next?`${barbers.find(b=>b.id===next.barber).name} · ${bookingName(next)}`:'Pick your barber and find a time that fits.'}</p><button class="text-btn" data-${next?'view="bookings"':'action="start"'}>${next?'Manage appointment':'Find my next cut'} ${icon('arrow')}</button></section></div></div><div class="section-head"><h2>Good people. Great cuts.</h2><button class="text-btn" data-action="start">Meet your barber ${icon('arrow')}</button></div><div class="barber-grid">${barbers.map(barberCard).join('')}</div>`;}
function selectedSummary(){return `<div class="selection-summary">${photo(B())}<div><strong>${B().name}</strong><p class="muted" style="font-size:12px">${S().name} · ${S().min} min · ${money(S().price)}</p></div><button class="text-btn" data-step="0" style="margin-left:auto">Change</button></div>`;}
function booking(){const titles=['Choose your barber.','Choose your services.','Make time for a good cut.','A final look.'];return `<div class="booking-wrap"><button class="back" data-action="booking-back">${icon('back')} ${state.step?'Back':'Back to home'}</button><div class="stepper-caption"><span>${state.editing?'Reschedule your visit':'Book your next visit'}</span><span>Step ${state.step+1} of 4</span></div><div class="stepper">${[0,1,2,3].map(i=>`<span class="${i<=state.step?'done':''}"></span>`).join('')}</div>${head(titles[state.step],['A great cut starts with the right person.','Choose one or more. Time and price update together.','All times shown in Arizona local time.','Review your visit before confirming.'][state.step])}${state.step===0?`<div class="booking-choices">${barbers.map(b=>`<button class="choice ${state.barber===b.id?'selected':''}" data-barber="${b.id}" aria-pressed="${state.barber===b.id}">${photo(b,'avatar square')}<div class="details"><h3>${b.name}</h3><p>${b.specialty}</p></div><span class="check">${state.barber===b.id?icon('check'):''}</span></button>`).join('')}</div>`:state.step===1?`${selectedSummary()}<div class="booking-choices">${servicesFor(state.barber).filter(s=>s.active!==false).map(s=>`<button class="choice ${(state.services||[state.service]).includes(s.id)?'selected':''}" data-service="${s.id}" role="checkbox" aria-checked="${(state.services||[state.service]).includes(s.id)}">${serviceIcon(s)}<div class="details"><h3>${s.name}</h3><p>${s.desc}<br>${s.min} minutes</p></div><strong class="price">${money(s.price)}</strong><span class="check">${(state.services||[state.service]).includes(s.id)?icon('check'):''}</span></button>`).join('')}</div>`:state.step===2?`${selectedSummary()}<div class="section-head"><h2>${pretty(state.date,{month:'long',year:'numeric'})}</h2></div><div class="dates" role="group" aria-label="Appointment date">${days.map(d=>`<button class="date ${state.date===d?'selected':''}" data-date="${d}" aria-pressed="${state.date===d}"><span>${pretty(d,{weekday:'short'})}</span><strong>${dateObj(d).getDate()}</strong><span>${pretty(d,{month:'short'})}</span></button>`).join('')}</div><h3>Available times</h3><p class="muted" style="font-size:12px;margin:8px 0 16px">${S().min}-minute appointment · Choose a time below.</p><div class="time-grid" role="group" aria-label="Appointment time">${times.map((t,i)=>{const unavailable=HFAppRules.appointmentAt({date:state.date,time:t})<=Date.now()||sampleBusy(t,S().min)||bookings.some(b=>b.id!==state.editing&&b.status!=='cancelled'&&b.barber===state.barber&&b.date===state.date&&overlaps(t,S().min,b.time,bookingDuration(b)));return `<button class="time ${state.time===t?'selected':''}" data-time="${t}" aria-pressed="${state.time===t}" ${unavailable?'disabled title="Already booked"':''}>${t}</button>`}).join('')}</div>`:review()}${state.step<3?`<div class="booking-footer"><div><strong>${state.step>0?money(S().price):'Your next great cut'}</strong><p>${state.step>0?`${S().name} · ${S().min} minutes`:'Choose the person behind your new look.'}</p></div>${button(`${state.step===2?'Review appointment':'Continue'} ${icon('arrow')}`,'next','',(state.step===2&&!state.time)||(state.step===1&&!selectedServices().length)?'disabled':'')}</div>`:''}</div>`;}
function minutes(s){const [t,p]=s.split(' ');let[h,m]=t.split(':').map(Number);return (h%12+(p==='PM'?12:0))*60+m;}
function sampleBusy(t,len){return [['10:00 AM',30],['11:00 AM',45],['12:00 PM',60],['1:00 PM',20]].some(([busy,duration])=>overlaps(t,len,busy,duration))||extras.blocks.some(b=>b.barber===state.barber&&b.date===state.date&&minutes(t)<clockMinutes(b.end)&&minutes(t)+len>clockMinutes(b.start));}
function overlaps(t,len,other,otherLen){return minutes(t)<minutes(other)+otherLen&&minutes(other)<minutes(t)+len;}
function review(){return `<div class="review-grid"><section class="panel"><div class="row">${photo(B(),'avatar square')}<div><h3>${B().name}</h3><p class="muted">${S().name}</p></div></div><div class="line-item" style="margin-top:20px"><span class="muted">Your visit</span><strong>${pretty(state.date)}</strong></div><div class="line-item"><span class="muted">Time</span><strong>${state.time}</strong></div><div class="line-item"><span class="muted">Location</span><strong>${shops[state.editing?(bookings.find(b=>b.id===state.editing)?.location||extras.location):(extras.location||'scottsdale')].name}</strong></div><div class="line-item"><span class="muted">Booked duration</span><strong>${S().min} minutes</strong></div><div class="line-item"><span class="muted">Service estimate</span><strong>${money(S().price)}</strong></div></section><section class="panel"><h2>Settle up after your cut.</h2><p class="muted" style="margin-top:14px">Your barber can add, remove or change services on your live ticket. When your visit is finished, you’ll review the final services and prices, approve the ticket, and choose an optional tip.</p><div class="notice">No tip and no payment at booking. The amount here is an estimate, not an approved final charge.</div>${button(state.editing?'Confirm new time':'Confirm booking','confirm','full','style="margin-top:24px"')}</section></div>`;}
function success(){const b=bookings.find(x=>x.id===state.latest)||upcoming();if(!b)return customerHome();return `<section class="success"><div class="success-mark">${icon('check')}</div><h1>You’re booked.</h1><p>A fresh cut. A little confidence.<br>We’ll see you in the chair.</p><div class="panel"><div class="row">${photo(barbers.find(x=>x.id===b.barber),'avatar square')}<div><h3>${barbers.find(x=>x.id===b.barber).name}</h3><p>${bookingName(b)}</p><small>${pretty(b.date)} at ${b.time}</small></div></div><div class="line-item" style="margin-top:15px"><span>Booked service estimate</span><strong>${money(b.estimateCents/100)}</strong></div></div>${button(`${icon('calendar')} Add to calendar`,'calendar-download','secondary full')}${button('View my appointments','visits','full')}</section>`;}
function oldMyBookings(){const list=[...bookings].reverse();return `${head('Your time in the chair.','Upcoming visits and past appointments.',button('Book a cut','start','small'))}${!list.length?`<div class="empty">${icon('calendar')}<h2>Your next chapter starts here.</h2><p>No appointments yet. Find a barber you connect with and pick your first visit.</p>${button('Find my barber','start')}</div>`:list.map(b=>{const barber=barbers.find(x=>x.id===b.barber),service=services.find(x=>x.id===b.service);return `<section class="appointment-card"><div class="row between"><span class="date-label">${pretty(b.date)} · ${b.time}</span><span class="badge ${b.status==='cancelled'?'cancelled':''}">${b.status==='cancelled'?'Cancelled':checked[b.id]?'Checked in':'Confirmed'}</span></div><div class="row" style="margin-top:15px">${photo(barber)}<div><h3 style="margin:0 0 5px">${service.name}</h3><p>${barber.name} · ${service.min} min · ${money(b.total)}</p></div></div>${b.status!=='cancelled'?`<div class="appointment-actions">${button('Reschedule','reschedule','secondary small',`data-id="${b.id}"`)}${button('Cancel visit','cancel','secondary small',`data-id="${b.id}"`)}</div>`:''}${state.cancelId===b.id?`<div class="confirmation">Cancel this appointment? Your selected time will become available again.<div class="flex-buttons">${button('Keep appointment','keep','secondary small')}${button('Yes, cancel visit','cancel-confirm','danger small',`data-id="${b.id}"`)}</div></div>`:''}</section>`}).join('')}`;}
function oldRewards(){return `<div class="reward-page">${head('Good looks. Great rewards.','Your loyalty looks good on you.')}${rewardCard()}<div class="section-head"><h2>A little something for you.</h2></div><div class="list"><div class="list-item">${icon('gift')}<div class="details"><strong>$10 off your next cut</strong><p>Two more visits to unlock your reward.</p></div><span class="pill">3 / 5</span></div><div class="list-item">${icon('crown')}<div class="details"><strong>The birthday treatment</strong><p>A little celebration, just for you.</p></div><span class="badge">Member perk</span></div></div>${button('Book my next visit','start','full','style="margin-top:24px"')}</div>`;}
function chat(){return `<div class="booking-wrap">${head('A word with your barber.','conversation · Messages stay on this browser.')}<div class="row" style="border-bottom:1px solid var(--line);padding-bottom:18px">${photo(activeStaff())}<div><h3>Lara</h3><small>Replies at the shop</small></div></div><div class="message-bubble">Hey John! Looking forward to your next visit. Let me know if you have a new style in mind.</div>${messages.map(m=>`<div class="message-bubble out">${esc(m)}</div>`).join('')}<form id="message-form" class="message-form"><input name="message" aria-label="Your message" maxlength="500" placeholder="Write a message…" required autocomplete="off"><button class="btn" type="submit" aria-label="Save message">${icon('send')}</button></form><p class="data-source">Messages are not sent to a real barber.</p></div>`;}
function metrics(owner=false){const active=bookings.filter(b=>b.status!=='cancelled');return `<div class="metric-strip">${(owner?[['Revenue today','$2,842','+12% vs previous Tuesday'],['Appointments',String(48+active.filter(b=>b.date===today).length),`${active.filter(b=>b.date===today).length} added today in this demo`],['Average ticket','$59','+6% vs previous Tuesday'],['Chairs booked','84%','2 barbers on the floor']]:[['Booked today','$320','6 appointments'],['Next appointment','10:00','Alex Morgan · Signature cut'],['Completed visits',String(bookings.filter(b=>b.ticket?.status==='approved'&&b.barber===activeBarberId()).length),'Client-approved tickets'],['This week','$1,280','+12.4% vs last week']]).map(([label,v,change])=>`<div class="metric"><span>${label}</span><strong class="num">${v}</strong><small>${change}</small></div>`).join('')}</div>`;}
const sampleSlots=[['10:00 AM','Alex Morgan','Signature haircut','30 min','alex'],['11:00 AM','Ryan Smith','Haircut + beard','45 min','jordan'],['1:00 PM','Marcus Reed','Beard sculpt','20 min','chris']];
function currentCheckins(){return Object.entries(checked).filter(([id,on])=>on&&(id.includes(':'+state.calendarDate+':')||bookings.some(b=>b.id===id&&b.date===state.calendarDate&&b.barber===activeBarberId()&&b.status!=='cancelled'))).length;}
function timeline(){
 const entries=sampleSlots.map(([time,name,service,duration,img],i)=>({time,name,service,duration,img,amount:[3000,4000,2000][i],id:'sample'+i+':'+state.calendarDate+':alex',isNew:false})).filter(s=>!bookings.some(b=>b.id===s.id));
 entries.push({time:'12:00 PM',isBreak:true});
 for(const b of bookings.filter(b=>b.status!=='cancelled'&&b.date===state.calendarDate&&(state.role==='Owner HQ'||b.barber===activeBarberId()))){const svc={name:bookingName(b),min:bookingDuration(b)};entries.push({time:b.time,name:b.client,barber:b.barber,amount:b.ticket?.approval?.subtotalCents??b.estimateCents,completed:b.status==='completed'||b.ticket?.status==='approved',tipCents:b.ticket?.approval?.tipCents,service:svc.name,duration:svc.min+' min',id:b.id,isNew:true});}
 entries.sort((a,b)=>minutes(a.time)-minutes(b.time));
 return `<div class="calendar"><div class="calendar-head"><strong>${pretty(state.calendarDate,{weekday:'long',month:'short',day:'numeric'})}</strong><small>Arizona time</small></div><div class="timeline">${entries.map(b=>b.isBreak?`<div class="slot" style="min-height:64px"><time>${b.time}</time><div class="slot-block break">Lunch break · 1 hour</div></div>`:`<div class="slot"><time>${b.time}</time><div class="slot-block ${b.time==='11:00 AM'?'blue':''}">${appointmentPortrait({client:b.name,barber:b.barber||activeBarberId()})}<div class="details"><h3>${esc(b.name)}${clientRecords.find(c=>c.name===b.name)?.visits===0?'<span class="new-customer-badge">New customer</span>':''}</h3><p>${b.service} · ${b.duration}${b.amount?' · '+cents(b.amount):''}${b.completed&&b.tipCents?' + '+cents(b.tipCents)+' tip':''}</p></div>${b.completed?'<span class="badge visit-completed">Completed</span>':`<button class="btn small ${checked[b.id]?'secondary':''}" data-action="checkin" data-id="${b.id}">${checked[b.id]?'Checked in':'Check in'}</button>`}</div></div>`).join('')}</div></div>`;
}
function proHome(){const active=bookings.filter(b=>b.status!=='cancelled'&&b.barber===activeBarberId());return `${head('Your chair. Your day.','A good day starts with a clear plan.',`<span class="pill"><span class="dot"></span> Accepting bookings</span>`)}${metrics()}<div class="dashboard-grid"><section><div class="section-head"><h2>In the chair today</h2><button class="text-btn" data-action="tomorrow">${state.calendarDate===today?'View tomorrow':'View today'} ${icon('arrow')}</button></div>${timeline()}</section><aside><div class="section-head"><h2>Keep the momentum.</h2></div><section class="panel"><div class="row">${photo(activeStaff())}<div><h3>Lara</h3></div></div><div class="line-item" style="margin-top:20px"><span class="muted">Next opening</span><strong>2:30 PM</strong></div><div class="line-item"><span class="muted">Checked in</span><strong>${currentCheckins()} check-ins</strong></div><button class="text-btn" data-view="availability">Manage my availability ${icon('arrow')}</button></section>${active.length?`<div class="section-head"><h2>New from the demo</h2></div>${active.slice(-2).map(b=>`<div class="list-item">${appointmentPortrait(b)}<div><strong>${esc(b.client)} · ${pretty(b.date)}</strong><p>${b.time} · ${bookingName(b)}</p></div></div>`).join('')}`:`<div class="notice">Try making a Customer booking, then return here to see it in the schedule.</div>`}</aside></div>`;}
function oldProCalendar(owner=false){return `${head(owner?'Every chair in sync.':'Your day, clearly laid out.',owner?'Master calendar · All barbers':'Your appointment schedule',`<div class="date-nav"><button class="icon-btn" data-action="prev-day" aria-label="Previous day">${icon('back')}</button><strong>${pretty(state.calendarDate)}</strong><button class="icon-btn" data-action="next-day" aria-label="Next day">${icon('chevron')}</button></div>`)}${timeline()}`;}
function oldClients(){return `${head('People, not just appointments.','Keep the little details that make a difference.')}<div class="list">${[['Alex Morgan','8 visits · Low taper, keep length on top.','alex'],['Ryan Smith','3 visits · Haircut + beard. Prefers mornings.','jordan'],['Jordan Lee','5 visits · Beard sculpt. Hot towel finish.','chris']].map(([n,d,img])=>`<div class="list-item">${photo({name:n,img:img+'.jpg'},'avatar square')}<div class="details"><strong>${n}</strong><p>${d}</p></div><span class="badge">Regular</span></div>`).join('')}</div>`;}
function earnings(){return `${head('Craft well. Earn well.','Your week in numbers. All figures are illustrative.')}${metrics()}<div class="dashboard-grid"><section class="panel"><h2>Your weekly breakdown</h2><div class="line-item" style="margin-top:15px"><span class="muted">Services</span><strong>$1,120</strong></div><div class="line-item"><span class="muted">Tips</span><strong>$160</strong></div><div class="line-item total"><strong>Total earned</strong><strong>$1,280</strong></div><p class="chart-note">24 completed cuts · $53.33 average including tips</p></section><section class="panel"><div class="row between"><h2>Next payout</h2>${icon('wallet')}</div><h1 style="margin:24px 0 8px">$1,280</h1><p class="muted">Friday · Account ending in 4242</p></section></div>`;}
function oldAvailability(){return `${head('Make room for life.','Preview your weekly availability.')}<div class="booking-wrap" style="margin-left:0"><form id="hours-form" class="panel"><h2>Weekly booking hours</h2><div class="field"><label for="start-time">Start time · Monday–Friday</label><input type="time" id="start-time" name="start" value="09:00" required></div><div class="field"><label for="end-time">Finish time · Monday–Friday</label><input type="time" id="end-time" name="end" value="18:00" required></div><p id="hours-error" class="confirmation" role="alert"></p><button type="submit" class="btn">Save hours</button><p id="hours-result" class="chart-note">Saturday 10 AM–4 PM · Sunday closed</p></form></div>`;}
function chart(){const vals=state.period==='Week'?[48,62,41,77,91,68,56]:[30,42,51,35,65,49,72,61,43,89,68,97,75,83];const labels=state.period==='Week'?['Tue','Wed','Thu','Fri','Sat','Sun','Mon']:vals.map((_,i)=>i%2===0?String(i*2+1):'');return `<div class="chart"><div class="chart-top"><div><h2>Revenue, in perspective.</h2></div><div class="segmented" aria-label="Chart period">${['Week','Month'].map(p=>`<button class="${state.period===p?'active':''}" data-period="${p}" aria-pressed="${state.period===p}">${p}</button>`).join('')}</div></div><div class="chart-bars" role="img" aria-label="${state.period} sample revenue chart, highest day ${state.period==='Week'?'Saturday at $2,730':'day 23 at $2,910'}">${vals.map((v,i)=>`<div class="bar-group"><span class="bar-value">${i%2===0?money(v*30):''}</span><div class="bar ${v===Math.max(...vals)?'highlight':''}" style="height:${v*1.5}px"></div><span class="bar-label">${labels[i]}</span></div>`).join('')}</div><div class="chart-axis"><span>Baseline: $0</span><span>Peak: ${money(Math.max(...vals)*30)}</span></div></div>`;}
function activity(){return `<div class="activity">${[['alex','Lara completed a haircut','2 min ago','+$40'],['jordan','New booking with Jose','12 min ago','+$30']].map(([id,label,when,amount])=>`<div class="list-item">${photo(barbers.find(b=>b.id===id))}<div class="details"><p style="color:var(--text);margin:0">${label}</p><small>${when}</small></div><span class="positive">${amount}</span></div>`).join('')}${bookings.filter(b=>b.status!=='cancelled').slice(-2).map(b=>`<div class="list-item">${icon('calendar')}<div class="details"><small>${pretty(b.date)} · ${b.time}</small></div><span class="positive">${money(b.ticket?.approval?b.ticket.approval.totalCents/100:b.estimateCents/100)}</span></div>`).join('')}</div>`;}
function ownerHome(){return `${head('A good day for the whole shop.',shops[extras.location||'scottsdale'].name+' · '+pretty(today,{weekday:'long',month:'long',day:'numeric'}),button(`${icon('calendar')} Master calendar`,'master','secondary small'))}${metrics(true)}<div class="dashboard-grid"><section>${chart()}<div class="section-head"><h2>On the floor</h2><button class="text-btn" data-view="team">Manage team ${icon('arrow')}</button></div>${barbers.map(b=>`<div class="list-item">${photo(b)}<div class="details"><strong>${b.name}</strong><p>${b.bookings} appointments this month</p></div><span class="badge">On shift</span></div>`).join('')}</section><aside><div class="section-head" style="margin-top:0"><h2>Live at the shop</h2><span class="dot"></span></div>${activity()}<div class="section-head"><h2>Keep things moving.</h2></div><div class="panel"><div class="row between">${icon('clock')}<span class="pill">2 open slots</span></div><h3 style="margin-top:18px">A little room this afternoon.</h3><p class="muted" style="font-size:13px;margin-top:8px">Lara has space at 2:30 PM. Jose has an opening at 4 PM.</p><button class="text-btn" data-action="master">View the calendar ${icon('arrow')}</button></div></aside></div>`;}
function oldTeam(){return `${head('Great people make the place.','Your team at McCormick Ranch.',button('Invite a barber','invite','small'))}<div class="table-wrap"><table><thead><tr><th>Barber</th><th>Appointments</th><th>Avg. ticket</th><th>Rating</th><th>Status</th></tr></thead><tbody>${barbers.map(b=>`<tr><td><div class="row">${photo(b)}<div><strong>${b.name}</strong><br><small>${b.specialty}</small></div></div></td><td>${b.bookings}</td><td>${money(b.ticket)}</td><td class="gold">${b.rating} / 5</td><td><span class="badge">On shift</span></td></tr>`).join('')}</tbody></table></div><section id="invite-panel" hidden class="panel" style="margin-top:24px;max-width:600px"><h2>Preview a team invitation</h2><form id="invite-form"><div class="field"><label for="invite-name">Barber’s name</label><input id="invite-name" name="name" maxlength="80" required placeholder="Full name"></div><div class="field"><label for="invite-email">Email address</label><input id="invite-email" name="email" type="email" required placeholder="barber@example.com"></div><button type="submit" class="btn">Preview invitation</button></form></section>`;}
function reports(){return `${head('Know what’s working.','Shop performance, without the guesswork.')}${metrics(true)}${chart()}<div class="section-head"><h2>Revenue by service</h2>${button('Export sample CSV','export','secondary small')}</div><div class="list">${[['Signature haircut','$12,640','51%'],['Haircut + beard','$8,320','34%'],['Beard sculpt','$2,180','9%'],['Kids haircut','$1,120','5%'],['Other services','$572','2%']].map(([n,v,p])=>`<div class="list-item">${icon('scissors')}<div class="details"><strong>${n}</strong></div><strong>${v}</strong><span class="muted" style="min-width:42px;text-align:right">${p}</span></div>`).join('')}</div>`;}
function settings(){return `${head('The details make the difference.','Your shop’s public-facing information.')}<form class="panel booking-wrap" id="shop-form" style="margin-left:0"><h2>Shop profile</h2><div class="field"><label for="shop-name">Shop name</label><input name="name" id="shop-name" value="${esc(extras.shopProfile?.name||'HAIRFLIX Barbershop')}" required maxlength="80"></div><div class="field"><label for="shop-location">Location</label><input name="location" id="shop-location" value="${esc(extras.shopProfile?.location||shops[extras.location||'scottsdale'].name)}" required maxlength="120"></div><div class="field"><label for="shop-policy">Cancellation notice</label><select id="shop-policy" name="notice" style="padding:14px;background:var(--bg);border:1px solid var(--line);border-radius:7px;color:var(--text)">${['24 hours','12 hours','48 hours'].map(h=>`<option ${extras.shopProfile?.notice===h?'selected':''}>${h}</option>`).join('')}</select></div><button class="btn" type="submit">Save changes</button><p id="shop-result" class="form-result" role="status"></p></form>`;}
document.addEventListener('click',e=>{const el=e.target.closest('button');if(!el||el.disabled)return;const d=el.dataset;if(d.role){state.role=d.role;state.calendarDate=today;go('home');return;}if(d.view){if(d.view==='book')startBooking();else go(d.view);return;}if(d.barber){state.barber=d.barber;state.time='';if(d.start){go('cBarberProfile');}else render();return;}if(d.service){const list=state.services||[state.service];state.services=list.includes(d.service)?list.filter(id=>id!==d.service):[...list,d.service];state.service=state.services[0]||'cut';state.time='';render();return;}if(d.date){state.date=d.date;state.time='';render();return;}if(d.time){state.time=d.time;render();return;}if(d.tip!==undefined){state.tip=Number(d.tip);render();return;}if(d.step!==undefined){state.step=Number(d.step);render();return;}if(d.period){state.period=d.period;render();return;}switch(d.action){case'start':startBooking();break;case'next':if((state.step===2&&!state.time)||(state.step===1&&!selectedServices().length))return;state.step++;render();window.scrollTo(0,0);break;case'booking-back':if(state.step){state.step--;render();}else go('home');break;case'confirm':confirmBooking();break;case'visits':go('bookings');break;case'reschedule':{const b=bookings.find(b=>b.id===d.id);state.editing=b.id;if(b.location)extras.location=b.location;state.barber=b.barber;state.service=b.service;state.services=b.services||[b.service];state.tip=0;state.date=days.includes(b.date)?b.date:days[0];state.time='';state.step=2;go('book');break;}case'cancel':state.cancelId=d.id;render();break;case'keep':state.cancelId=null;render();break;case'cancel-confirm':{const b=bookings.find(b=>b.id===d.id);b.status='cancelled';delete checked[b.id];save();state.cancelId=null;render();toast('appointment cancelled.');break;}case'calendar-download':downloadCalendar();break;case'checkin':openTicketFor(d.id);break;case'master':state.calendarDate=today;go('calendar');break;case'tomorrow':state.calendarDate=state.calendarDate===today?days[0]:today;render();break;case'prev-day':case'next-day':{const dt=dateObj(state.calendarDate);dt.setDate(dt.getDate()+(d.action==='next-day'?1:-1));state.calendarDate=iso(dt);render();break;}case'invite':go('hInvite');break;case'notifications':go(state.role==='Customer'?'cNotifications':state.role==='Barber Pro'?'pNotifications':'hNotifications');break;case'export':download('hairflix-sample-report.csv','Service,Revenue\nSignature haircut,12640\nHaircut + beard,8320\nBeard sculpt,2180\nKids haircut,1120\nOther services,572\n','text/csv');toast('Sample report downloaded.');break;case'reset':document.querySelector('#reset-confirm').innerHTML=`<div class="confirmation">Remove saved bookings, messages and check-ins from this browser?<div class="flex-buttons">${button('Keep data','reset-keep','secondary small')}${button('Reset data','reset-confirm','danger small')}</div></div>`;break;case'reset-keep':document.querySelector('#reset-confirm').innerHTML='';break;case'reset-confirm':bookings=[];messages=[];checked={};save();render();toast('data reset.');break;}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,data=new FormData(form);if(form.id==='message-form'){const m=String(data.get('message')||'').trim();if(!m)return;messages.push(m.slice(0,500));save();render();document.querySelector('[name="message"]').focus();toast('message saved on this browser.');}if(form.id==='hours-form'){const start=data.get('start'),end=data.get('end');if(end<=start){document.querySelector('#hours-error').textContent='Finish time must be later than start time.';return;}document.querySelector('#hours-error').textContent='';document.querySelector('#hours-result').textContent=`Preview: Monday–Friday, ${start}–${end}. Live availability is unchanged.`;toast('Weekly hours preview updated.');}if(form.id==='invite-form'){document.querySelector('#invite-result').textContent=`Invitation preview ready for ${data.get('name')} at ${data.get('email')}. `;}if(form.id==='shop-form'){extras.shopProfile={name:String(data.get('name')).trim(),location:String(data.get('location')).trim(),notice:String(data.get('notice'))};save();document.querySelector('#shop-result').textContent='Shop details saved.';}});
function confirmBooking(){if(!selectedServices().length){state.step=1;render();return;}if(!state.time||!times.includes(state.time)||HFAppRules.appointmentAt({date:state.date,time:state.time})<=Date.now()||sampleBusy(state.time,S().min)){toast('Choose an available time first.');state.step=2;render();return;}const collision=bookings.some(b=>b.id!==state.editing&&b.status!=='cancelled'&&b.barber===state.barber&&b.date===state.date&&overlaps(state.time,S().min,b.time,bookingDuration(b)));if(collision){state.time='';state.step=2;render();toast('That slot is now taken. Choose another time.');return;}const b={id:state.editing||String(Date.now()),barber:state.barber,service:state.services?.[0]||state.service,services:selectedServices().map(s=>s.id),bookedServices:selectedServices().map(s=>({...s})),durationMin:S().min,location:state.editing?(bookings.find(b=>b.id===state.editing)?.location||extras.location||'scottsdale'):(extras.location||'scottsdale'),date:state.date,time:state.time,tip:0,total:S().price,estimateCents:Math.round(S().price*100),status:'confirmed',client:'John B.'};if(state.editing){delete checked[state.editing];bookings=bookings.map(x=>x.id===state.editing?b:x);}else bookings.push(b);state.latest=b.id;save();go('success');}
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function downloadCalendar(){const b=bookings.find(x=>x.id===state.latest);if(!b)return;const [hh,mm]=[Math.floor(minutes(b.time)/60),minutes(b.time)%60];const start=b.date.replaceAll('-','')+'T'+String(hh).padStart(2,'0')+String(mm).padStart(2,'0')+'00';const endM=minutes(b.time)+bookingDuration(b);const end=b.date.replaceAll('-','')+'T'+String(Math.floor(endM/60)).padStart(2,'0')+String(endM%60).padStart(2,'0')+'00';download('hairflix-demo-appointment.ics',['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//HAIRFLIX//Demo//EN','BEGIN:VEVENT','UID:'+b.id+'@hairflix-demo','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').split('.')[0]+'Z','DTSTART;TZID=America/Phoenix:'+start,'DTEND;TZID=America/Phoenix:'+end,'SUMMARY:HAIRFLIX appointment','LOCATION:McCormick Ranch - sample location','DESCRIPTION:Prototype only. This is not a real appointment.','END:VEVENT','END:VCALENDAR'].join('\r\n'),'text/calendar');toast('calendar event downloaded.');}
